// Transform input data for JSON2Video API
try {
  const input = $input.item.json;
  const videos = input.Videos || [];
  const audioUrl = input.audio_url || input.speech_url || '';
  const videoId = input.ID || '';

  // Build timeline from video URLs
  const timeline = [];
  const videoDuration = 5.0; // Duration for each video clip

  videos.forEach((video, index) => {
    if (video && video.output) {
      timeline.push({
        "type": "video",
        "url": video.output,
        "duration": videoDuration,
        "effects": {
          "zoom": 1.0 // No zoom by default
        }
      });
    }
  });

  // If no videos, add a default placeholder
  if (timeline.length === 0) {
    timeline.push({
      "type": "image",
      "url": "https://via.placeholder.com/1080x1920/000000/FFFFFF?text=No+Videos",
      "duration": 3.0
    });
  }

  // Build JSON2Video render request
  const renderRequest = {
    "timeline": timeline,
    "transition": {
      "type": "crossfade",
      "duration": 0.5
    }
  };

  // Add audio if available
  if (audioUrl) {
    renderRequest.audio = audioUrl;
  }

  return [{
    json: {
      renderRequest,
      videoId,
      originalInput: input
    }
  }];

} catch (error) {
  return [{
    json: {
      error: true,
      message: `Error transforming input: ${error.message}`,
      renderRequest: {
        "timeline": [{
          "type": "image",
          "url": "https://via.placeholder.com/1080x1920/FF0000/FFFFFF?text=Error",
          "duration": 3.0
        }]
      }
    }
  }];
}
